function toEntry(r: Raw): SchoolCurriculumEntry {
  const sems = {} as Record<Sem, SemCurr>;
  SEMS.forEach((s) => {
    const sm = r.sems[s];
    const groups: CurrGroup[] = sm.g.map(([label, pick, cr], i) => ({
      id: `${r.id}-${s}-${i}`,
      label,
      pick,
      options: r.o[label].map((name) => ({ name, credits: cr })),
    }));
    sems[s] = { fixed: sm.f.map(([name, credits]) => ({ name, credits })), groups };
  });
  const curriculum: SchoolCurriculum = { school: r.school, year: "2026학년도 입학생", note: NOTE, sems };
  return { id: r.id, curriculum, source: { url: BASE + r.post, doc: r.file, year: "2026학년도 입학생", checked: r.checked ?? CHECKED } };
}

export const XLSX_CURRICULA: SchoolCurriculumEntry[] = RAW.map(toEntry);
